// 오름차순으로 정렬된 a[0..n-1]에서 x의 위치를 찾는다
int lo = 0, hi = n - 1;
while (lo <= hi) {                 // 이 반복이 몇 번 도는가
    int mid = (lo + hi) / 2;
    if (a[mid] == x) return mid;
    if (a[mid] < x) lo = mid + 1;
    else hi = mid - 1;
}
return -1;                         // 없음

